package com.graduation.snack.domain; import org.springframework.boot.CommandLineRunner;import org.springframework.core.annotation.Order;import org.springframework.context.annotation.*;
@org.springframework.context.annotation.Profile({"dev","test","ci"}) @Configuration public class ProjectDataSeed{@Bean @Order(10) CommandLineRunner seedProject(SnackProductRepository products, GroupCampaignRepository campaigns){return args->{if(products.count()==0){var x=new SnackProduct();x.setName("海盐苏打饼干");x.setBrand("Campus Select");x.setCategory("饼干");x.setPrice(new java.math.BigDecimal("12.90"));x.setStock(80);x.setStatus("ON_SALE");var saved=products.save(x);var c=new GroupCampaign();c.setProductId(saved.getId());c.setTitle("宿舍楼晚间拼团");c.setGroupPrice(new java.math.BigDecimal("9.90"));c.setTargetQuantity(20);c.setSoldQuantity(0);c.setStartTime(java.time.LocalDateTime.now().minusDays(1));c.setEndTime(java.time.LocalDateTime.now().plusDays(30));c.setStatus("ACTIVE");campaigns.save(c);}};}}
